	return fmt.Sprintf("Hello, %s! Selamat belajar Go!", name)
}

// Fungsi calculateArea: menghitung luas persegi panjang
func calculateArea(width, height float64) float64 {
	return width * height
}

func main() {
	// Panggil add
	result := add(15, 27)
	fmt.Println("15 + 27 =", result)

	// Panggil greet
	msg := greet("Gopher")
	fmt.Println(msg)

	// Panggil calculateArea
	area := calculateArea(5.5, 3.2)
	fmt.Printf("Luas: %.2f\n", area)
}
